  "tagline": "Know what to tip, before you tip.",
  "problem_statement": {
    "core_issue": "Social anxiety and financial uncertainty surrounding tipping culture.",
    "details": [
      "Customers often feel awkward asking staff about tipping norms.",
      "Inconsistent tipping leads to income instability for service workers.",
      "Tourists and locals alike lack a reliable, real-time reference for appropriate gratuity amounts at specific establishments."
    ]
  },
  "solution": {
    "product_name": "Tipperary",
    "description": "A crowdsourced mobile application that provides real-time, anonymized average tip percentages and dollar amounts for every restaurant, cafe, and bar.",
