      "Contextual Insights: Displays tips broken down by service quality ratings (e.g., 'Great Service' vs. 'Average Service').",
      "Fairness Score: A proprietary algorithm that highlights restaurants with equitable tipping practices versus those with outlier extremes.",
      "Offline Mode: Caches recent data for areas with poor connectivity."
    ]
  },
  "market_opportunity": {
    "target_audience": "Millennials and Gen Z diners who value transparency and social responsibility.",
    "market_size": "The global restaurant industry is valued at over $1 trillion, with tipping accounting for a significant portion of service worker income in North America and increasingly in other regions.",
    "growth_potential": "Expansion into other service industries such as ride-sharing, delivery services, and hospitality."
  },
  "business_model": {
    "revenue_streams": [
